sys_script_include.script:
var FieldUpdater = Class.create();
FieldUpdater.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateField: function() {
        try {
            var sn = this.getParameter('sysparm_sn_number');
            gs.info("[FieldUpdater] 开始处理序列号: " + sn);

            // 获取系统管理员的 sys_id
            var adminID = this.getAdminID();
            if (!adminID) {
                gs.error("[FieldUpdater] 找不到系统管理员用户");
                return JSON.stringify({ 
                    status: "error", 
                    message: "System Administrator not found" 
                });
            }

            var gr = new GlideRecord('x_1770592_easy_t_0_my_asset_inventory');
            gr.addQuery('serial_number', sn);
            gr.query();

            if (gr.next()) {
                gs.info("[FieldUpdater] 找到资产记录: " + gr.getUniqueValue());

                // 只更新 assigner 字段
                gr.assigner = adminID; // 直接属性赋值

                if (gr.update()) {
                    gs.info("[FieldUpdater] 更新成功! 记录: " + gr.getUniqueValue());
                    return JSON.stringify({ 
                        status: "success", 
                        assigner: adminID,
                        message: "Assigner updated to System Administrator "
                    });
                } else {
                    var errorMsg = gr.getLastErrorMessage() || "未知错误";
                    gs.error("[FieldUpdater] 更新失败: " + errorMsg);
                    return JSON.stringify({ 
                        status: "error", 
                        message: errorMsg 
                    });
                }
            } else {
                gs.error("[FieldUpdater] 找不到序列号对应的资产: " + sn);
                return JSON.stringify({ 
                    status: "not_found", 
                    message: "未找到序列号对应的资产记录" 
                });
            }
        } catch (ex) {
            gs.error("[FieldUpdater] 发生异常: " + ex);
            return JSON.stringify({ 
                status: "exception", 
                message: ex.message 
            });
        }
    },

    // 获取系统管理员 sys_id
    getAdminID: function() {
        // 方法1：直接使用系统预定义的管理员ID（如果知道）
        // return '6816f79cc0a8016401c5a33be04be441'; // 替换为实际管理员sys_id

        // 方法2：查找系统管理员用户
        var user = new GlideRecord('sys_user');

        // 先尝试用户名查找
        user.addQuery('user_name', 'admin');
        user.query();
        if (user.next()) return user.getUniqueValue();

        // 再尝试显示名查找
        user = new GlideRecord('sys_user');
        user.addQuery('name', 'System Administrator');
        user.query();
        if (user.next()) return user.getUniqueValue();

        // 最后尝试任何管理员角色用户
        user = new GlideRecord('sys_user');
        user.addQuery('roles', 'admin');
        user.addQuery('active', true);
        user.query();
        if (user.next()) return user.getUniqueValue();

        return null;
    },

    type: 'FieldUpdater'
});
